with valid as (select *, round(revenue / units, 2) as revenue_per_unit from store_sales where sale_date >= date '2023-03-23'), with_dims as (select a.*, d.product_name, d.price, d.category from valid a left join products d on a.product_id = d.id), metrics as (select id, store_id, revenue_per_unit, product_name, category, sum(revenue_per_unit) over (partition by store_id order by revenue_per_unit, id rows between unbounded preceding and current row) as cumulative_revenue_per_unit, row_number() over (partition by category order by revenue_per_unit, id) as event_seq, round(revenue / sum(revenue) over (partition by store_id), 4) as revenue_share, avg(price) over (partition by product_id, store_id order by price, id rows between 2 preceding and current row) as price_avg_2 from with_dims), joined as (select s.*, d.region from metrics s inner join stores d on s.store_id = d.id where d.region = 'South'), with_dims_store_sales as (select e.id, e.store_id, e.revenue_per_unit, e.product_name, e.cumulative_revenue_per_unit, e.revenue_share, b.opened_date from joined e left join stores b on e.store_id = b.id), metrics_store_sales as (select id, store_id, revenue_share, opened_date, avg(cumulative_revenue_per_unit) over (partition by store_id order by opened_date, id rows between 6 preceding and 1 preceding) as cumulative_revenue_per_unit_avg_6_prior, count(cumulative_revenue_per_unit) over (partition by store_id) as store_id_count_cumulative_revenue_per_unit, rank() over (partition by store_id order by revenue_per_unit) as revenue_per_unit_rank from with_dims_store_sales), with_dims_store_sales_2 as (select src.id, src.store_id, src.opened_date, src.revenue_per_unit_rank, p.city, p.sqft, p.opened_date as store_opened_date from metrics_store_sales src left join stores p on src.store_id = p.id) select case when sqft >= 12977 then 'LARGE' else 'SMALL' end as sqft_tier, sort_array(collect_set(city)) as city_list, avg(revenue_per_unit_rank) as avg_revenue_per_unit_rank, approx_percentile(sqft, array(0.25, 0.5, 0.75)) as sqft_quartiles from with_dims_store_sales_2 group by rollup (case when sqft >= 12977 then 'LARGE' else 'SMALL' end) order by sqft_tier
